cssCode:
.glass-reveal-wrap {
  width: 200px; height: 200px; position: relative;
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
  overflow: hidden; cursor: crosshair;
}
.glass-bg {
  position: absolute; width: 100%; height: 100%;
  background: conic-gradient(#ff007f, #6c63ff, #00ffcc, #ff007f);
  animation: spinGlass 4s linear infinite; opacity: 0.3;
  transition: opacity 0.5s;
}
.glass-reveal-wrap:hover .glass-bg { opacity: 1; }
.glass-overlay {
  position: absolute; inset: 5px; background: rgba(26,26,26,0.8);
  border-radius: 50%; backdrop-filter: blur(10px);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 40px; font-family: sans-serif;
  border: 1px solid rgba(255,255,255,0.1);
}
@keyframes spinGlass { 100% { transform: rotate(360deg); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'glass-reveal-wrap';

const bg = document.createElement('div');
bg.className = 'glass-bg';

const overlay = document.createElement('div');
overlay.className = 'glass-overlay';
overlay.innerText = '💎';

wrap.appendChild(bg);
wrap.appendChild(overlay);
c.appendChild(wrap);
